import attr
from typing import Union

from taf.ul.ue.sim.env_setup.utils.enums import DevicesNames
from ute_testline_configuration.ute_config import CUS as CusUteConfig  # type: ignore
from taf.config.testline.ue import CUS as CusTafConfig  # type: ignore
from taf.ul.ue.sim.env_setup.devices.rtg_cus_generic import RtgCusGenericInterface


@attr.s
class RTG(RtgCusGenericInterface):
    idx = attr.ib(type=int)
    remote_host = attr.ib(type=str)
    output_directory_path = attr.ib(type=str)
    configuration = attr.ib(type=Union[CusUteConfig, CusTafConfig], hash=False)
    config_type = attr.ib(type="str")
    name = attr.ib(default=DevicesNames.RTG, init=False)

    def _get_taf_pdu_config(self):
        return self.configuration.pdu_port
